import Foundation

// Runtime translation tables, keyed by the English source string. English is
// the base (no table). Coverage is assembled from focused per-screen "slices"
// (each covering all eight languages) so the file stays reviewable as it
// grows. Missing keys fall back to English at lookup time, so partial
// coverage is always safe.
//
// Format keys use printf placeholders (%@, %d) and are fed through
// `String(format:)` by the variadic `L(_:_:)`.
enum TranslationTables {
    static let tables: [AppLanguage: [String: String]] = merge([
        pickerSlice,
        onboardingSlice,
        onboardingScreensSlice,
        interestsSlice,
        loginSlice,
        studySlice,
        librarySlice,
        exploreSlice,
        chatSlice,
        settingsSlice,
        createDeckSlice,
        createTabsSlice,
        sessionSlice,
        deckSlice,
        wordInfoSlice,
        planPremiumSlice,
        statsSlice,
        sheetsSlice,
        attributeSlice,
        profileSlice,
        interestParentsSlice,
        interestSubchipsSlice,
        miscSlice,
    ])

    // Combines slices into one table per language (later slices win on key
    // collisions, though keys are expected to be unique across slices).
    private static func merge(_ slices: [[AppLanguage: [String: String]]]) -> [AppLanguage: [String: String]] {
        var out: [AppLanguage: [String: String]] = [:]
        for slice in slices {
            for (lang, dict) in slice {
                out[lang, default: [:]].merge(dict) { _, new in new }
            }
        }
        return out
    }

