            "Open Generate, make a story, conversation, song, poem, news article, or joke — then tap the bookmark on the result to keep it here.": "Abre Generar, crea una historia, conversación, canción, poema, artículo de noticias o chiste, y luego toca el marcador en el resultado para guardarlo aquí.",
            "Forgetting curve": "Curva del olvido",
            "Average chance the deck is still remembered each day from today, projecting forward without further review.": "Probabilidad media de que el mazo siga recordándose cada día a partir de hoy, proyectada hacia adelante sin más repasos.",
