            "The bars": "Las barras",
            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "Cuatro barras verticales indican cuánto de este mazo aún necesita atención. Cada barra representa aproximadamente una cuarta parte de tus tarjetas: las barras se llenan a medida que se acumulan tarjetas que aún no has estudiado o que ya toca repasar. Estudiar vacía las barras a medida que el planificador aleja esas tarjetas en el tiempo.",
            "\"New\"": "«Nuevo»",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "«Nuevo» aparece cuando aún no has repasado ninguna tarjeta de este mazo. Las cuatro barras están llenas porque todo el mazo está pendiente: toca Reproducir para empezar una sesión y las barras retroceden a medida que calificas tarjetas.",
            "\"Up to date\"": "«Al día»",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "«Al día» aparece cuando no hay tarjetas pendientes y ya has estudiado cada tarjeta al menos una vez: las cuatro barras están vacías. Vuelve más tarde y las barras se llenarán a medida que las tarjetas reaparezcan según su calendario.",
            "Clearing the bars": "Vaciar las barras",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "Toca el botón Reproducir en la parte superior de este mazo para iniciar una sesión de tarjetas. Las barras se actualizan después de cada sesión a medida que el planificador reordena tus tarjetas.",
            "Target retention": "Retención objetivo", "Current": "Actual", "What it means": "Qué significa",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "La retención objetivo es la probabilidad con la que quieres recordar cada tarjeta la próxima vez que toque repasarla. Al 90 %, aceptas que aproximadamente 1 de cada 10 tarjetas se habrá olvidado cuando llegue su repaso; el planificador apunta exactamente a esa tasa de acierto.",
            "How it affects scheduling": "Cómo afecta a la programación",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "Los porcentajes más altos aprietan la programación: las tarjetas vuelven antes, así olvidas menos, pero estudias más a menudo. Los porcentajes más bajos alargan los intervalos entre repasos, así estudias menos, a costa de olvidar más tarjetas por el camino.",
            "Range": "Rango",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "Elige entre 80 % y 98 %. 90 % es el valor predeterminado y el que Anki recomienda para la mayoría de los estudiantes: un equilibrio entre carga de estudio y retención.",
            "When to change it": "Cuándo cambiarlo",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "Súbelo un poco si demasiadas tarjetas te resultan poco familiares cuando reaparecen. Bájalo si te sientes abrumado por los repasos diarios y puedes permitirte olvidar algunas más.",
