            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "Quatre barres verticales indiquent la part de ce paquet qui demande encore de l'attention. Chaque barre représente environ un quart de tes cartes — les barres se remplissent à mesure que s'accumulent les cartes pas encore étudiées ou de nouveau dues. Étudier vide les barres à mesure que le planificateur repousse ces cartes plus loin.",
            "\"New\"": "« Nouveau »",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "« Nouveau » apparaît quand tu n'as encore révisé aucune carte de ce paquet. Les quatre barres sont pleines car tout le paquet est en attente — touche Lecture pour démarrer une session et les barres reculent à mesure que tu notes les cartes.",
            "\"Up to date\"": "« À jour »",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "« À jour » apparaît quand aucune carte n'est due et que tu as déjà étudié chaque carte au moins une fois — les quatre barres sont vides. Reviens plus tard et les barres se rempliront à mesure que les cartes réapparaîtront selon leur planning.",
            "Clearing the bars": "Vider les barres",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "Touche le bouton Lecture en haut de ce paquet pour démarrer une session de cartes. Les barres se mettent à jour après chaque session, à mesure que le planificateur réorganise tes cartes.",
            "Target retention": "Rétention cible", "Current": "Actuel", "What it means": "Ce que cela signifie",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "La rétention cible est la probabilité avec laquelle tu veux te souvenir de chaque carte lors de sa prochaine révision. À 90 %, tu acceptes qu'environ 1 carte sur 10 soit oubliée au moment de sa révision — le planificateur vise exactement ce taux de réussite.",
            "How it affects scheduling": "Effet sur la planification",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "Des pourcentages plus élevés resserrent le planning — les cartes reviennent plus tôt, tu oublies donc moins, mais tu étudies plus souvent. Des pourcentages plus bas allongent les intervalles entre révisions, tu étudies donc moins, au prix d'oublier davantage de cartes en chemin.",
            "Range": "Plage",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "Choisis entre 80 % et 98 %. 90 % est la valeur par défaut, celle qu'Anki recommande pour la plupart des apprenants — un compromis équilibré entre charge d'étude et rétention.",
            "When to change it": "Quand le modifier",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "Augmente-le légèrement si trop de cartes te semblent peu familières à leur réapparition. Baisse-le si tu te sens submergé par les révisions quotidiennes et peux te permettre d'en oublier quelques-unes de plus.",
            "View": "Affichage", "Story": "Histoire", "Line by line": "Ligne par ligne", "You asked for": "Ta demande",
            "Showing %d %@ for:": "Affichage de %d %@ pour :", "Regenerate": "Régénérer", "Saving…": "Enregistrement…",
            "Create New Deck": "Créer un paquet", "Add to Deck": "Ajouter au paquet", "Something went wrong": "Une erreur s'est produite",
            "Adding…": "Ajout…", "Remove": "Retirer", "Prompt sent to Claude": "Consigne envoyée à Claude",
            "Raw JSON response": "Réponse JSON brute", "Generation Details": "Détails de la génération",
            "PUBLIC": "PUBLIC", "YES": "OUI", "NO": "NON", "Coming soon": "Bientôt disponible", "TITLE": "TITRE",
            "Deck title": "Titre du paquet", "COVER": "COUVERTURE", "Save deck": "Enregistrer le paquet", "New Deck": "Nouveau paquet",
            "Alphabetized": "Alphabétique", "Original": "Original", "Conversation": "Conversation", "News Article": "Article de presse",
            "Songs": "Chansons", "Poems": "Poèmes", "Jokes": "Blagues",
            "Add Synonyms": "Ajouter des synonymes", "Add Antonyms": "Ajouter des antonymes", "Create Sentence": "Créer une phrase",
            "Add Plurals": "Ajouter des pluriels", "Add Conjugations": "Ajouter des conjugaisons", "Add Similar Sounding Words": "Ajouter des mots au son similaire", "Add Similar-Looking Words": "Ajouter des mots à l'aspect similaire",
            "Gradient": "Dégradé", "Audio": "Audio", "Black": "Noir", "White": "Blanc", "Dark Cherry": "Cerise foncée",
            "Pleasant": "Agréable", "Mouths": "Bouches", "Mouths 2": "Bouches 2", "Speakers": "Locuteurs", "Speakers 2": "Locuteurs 2",
            "Porcelain": "Porcelaine", "Porcelain 2": "Porcelaine 2", "Byzantine": "Byzantin", "Byzantine 2": "Byzantin 2",
            "Still Life": "Nature morte", "Chinese Village": "Village chinois",
            "Colors": "Couleurs", "Graphics": "Graphismes", "Art": "Art", "Medieval": "Médiéval",
        ],
        .de: [
            "Rename": "Umbenennen", "Merge into": "Zusammenführen mit", "Download as audio": "Als Audio herunterladen",
            "Export as CSV": "Als CSV exportieren", "Delete deck": "Stapel löschen", "Merged": "Zusammengeführt", "OK": "OK",
            "Added %d %@ to \"%@\".": "%d %@ zu „%@\" hinzugefügt.", "Delete this deck?": "Diesen Stapel löschen?",
            "Delete": "Löschen", "Cancel": "Abbrechen", "This can't be undone.": "Das kann nicht rückgängig gemacht werden.",
            "Couldn't generate more": "Konnte nicht mehr generieren", "Delete this artifact?": "Dieses Artefakt löschen?",
            "Delete artifact": "Artefakt löschen", "%d due": "%d fällig", "New": "Neu", "Up to date": "Aktuell",
            "CONTENT": "INHALT", "ARTIFACTS": "ARTEFAKTE", "STATS": "STATISTIK", "Copy": "Kopieren",
            "Generating…": "Wird generiert…", "Generate More": "Mehr generieren", "No artifacts saved yet": "Noch keine Artefakte gespeichert",
            "Open Generate, make a story, conversation, song, poem, news article, or joke — then tap the bookmark on the result to keep it here.": "Öffne „Generieren\", erstelle eine Geschichte, ein Gespräch, ein Lied, ein Gedicht, einen Nachrichtenartikel oder einen Witz – tippe dann auf das Lesezeichen am Ergebnis, um es hier zu behalten.",
            "Forgetting curve": "Vergessenskurve",
            "Average chance the deck is still remembered each day from today, projecting forward without further review.": "Durchschnittliche Wahrscheinlichkeit, dass der Stapel ab heute an jedem Tag noch erinnert wird – ohne weitere Wiederholung hochgerechnet.",
            "Review some cards to start the curve.": "Wiederhole ein paar Karten, um die Kurve zu starten.", "Target %d%%": "Ziel %d%%",
            "Today": "Heute", "+%dd": "+%dT", "Most at risk": "Am meisten gefährdet",
            "Cards with the highest forgetting risk right now. Review these first.": "Karten mit dem höchsten Vergessensrisiko im Moment. Wiederhole diese zuerst.",
            "No cards at risk — keep up the good work.": "Keine Karten gefährdet – weiter so.", "Generate Artifact": "Artefakt generieren",
            "Prompt": "Vorgabe", "(none)": "(keine)", "Topics": "Themen", "Tone": "Ton", "Settings": "Einstellungen",
            "Language": "Sprache", "Level": "Niveau", "Content": "Inhalt", "Original size": "Ursprüngliche Größe",
            "Original Prompt": "Ursprüngliche Vorgabe", "Done": "Fertig", "Review queue": "Wiederholungswarteschlange", "Status": "Status",
            "The bars": "Die Balken",
            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "Vier senkrechte Balken zeigen, wie viel dieses Stapels noch Aufmerksamkeit braucht. Jeder Balken steht für etwa ein Viertel deiner Karten – die Balken füllen sich, wenn sich noch nicht gelernte oder erneut fällige Karten anhäufen. Das Lernen leert die Balken, während der Planer diese Karten weiter nach hinten schiebt.",
            "\"New\"": "„Neu\"",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "„Neu\" erscheint, wenn du noch keine Karte dieses Stapels wiederholt hast. Alle vier Balken sind voll, weil der ganze Stapel aussteht – tippe auf Wiedergabe, um eine Sitzung zu starten, und die Balken gehen zurück, während du Karten bewertest.",
            "\"Up to date\"": "„Aktuell\"",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "„Aktuell\" erscheint, wenn gerade keine Karten fällig sind und du jede Karte mindestens einmal gelernt hast – alle vier Balken sind leer. Komm später wieder, und die Balken füllen sich, wenn Karten planmäßig wieder auftauchen.",
            "Clearing the bars": "Die Balken leeren",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "Tippe oben an diesem Stapel auf Wiedergabe, um eine Karteikartensitzung zu starten. Die Balken aktualisieren sich nach jeder Sitzung, während der Planer deine Karten neu ordnet.",
            "Target retention": "Ziel-Behaltensrate", "Current": "Aktuell", "What it means": "Was es bedeutet",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "Die Ziel-Behaltensrate ist die Wahrscheinlichkeit, mit der du dich beim nächsten Fälligwerden an jede Karte erinnern willst. Bei 90 % akzeptierst du, dass etwa 1 von 10 Karten bis zur Wiederholung vergessen ist – der Planer strebt genau diese Trefferquote an.",
            "How it affects scheduling": "Wie es die Planung beeinflusst",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "Höhere Prozentwerte straffen den Plan – Karten kommen früher zurück, du vergisst weniger, lernst aber häufiger. Niedrigere Prozentwerte dehnen die Abstände zwischen Wiederholungen, du lernst weniger – auf Kosten von mehr vergessenen Karten unterwegs.",
            "Range": "Bereich",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "Wähle zwischen 80 % und 98 %. 90 % ist der Standardwert und der von Anki für die meisten Lernenden empfohlene – ein ausgewogener Kompromiss zwischen Lernaufwand und Behalten.",
            "When to change it": "Wann man ihn ändert",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "Erhöhe ihn etwas, wenn dir beim Wiederauftauchen zu viele Karten fremd vorkommen. Senke ihn, wenn du dich von den täglichen Wiederholungen erschlagen fühlst und es dir leisten kannst, ein paar mehr zu vergessen.",
            "View": "Ansicht", "Story": "Geschichte", "Line by line": "Zeile für Zeile", "You asked for": "Deine Anfrage",
            "Showing %d %@ for:": "%d %@ werden angezeigt für:", "Regenerate": "Neu generieren", "Saving…": "Wird gespeichert…",
            "Create New Deck": "Neuen Stapel erstellen", "Add to Deck": "Zum Stapel hinzufügen", "Something went wrong": "Etwas ist schiefgelaufen",
            "Adding…": "Wird hinzugefügt…", "Remove": "Entfernen", "Prompt sent to Claude": "An Claude gesendete Vorgabe",
            "Raw JSON response": "Rohe JSON-Antwort", "Generation Details": "Generierungsdetails",
