        .it: [
            "Rename": "Rinomina", "Merge into": "Unisci a", "Download as audio": "Scarica come audio",
            "Export as CSV": "Esporta come CSV", "Delete deck": "Elimina mazzo", "Merged": "Unito", "OK": "OK",
            "Added %d %@ to \"%@\".": "Aggiunti %d %@ a \"%@\".", "Delete this deck?": "Eliminare questo mazzo?",
            "Delete": "Elimina", "Cancel": "Annulla", "This can't be undone.": "Questa azione non può essere annullata.",
            "Couldn't generate more": "Impossibile generarne altri", "Delete this artifact?": "Eliminare questo artefatto?",
            "Delete artifact": "Elimina artefatto", "%d due": "%d da rivedere", "New": "Nuovo", "Up to date": "Aggiornato",
            "CONTENT": "CONTENUTO", "ARTIFACTS": "ARTEFATTI", "STATS": "STATISTICHE", "Copy": "Copia",
            "Generating…": "Generazione…", "Generate More": "Genera altri", "No artifacts saved yet": "Nessun artefatto salvato ancora",
            "Open Generate, make a story, conversation, song, poem, news article, or joke — then tap the bookmark on the result to keep it here.": "Apri Genera, crea una storia, una conversazione, una canzone, una poesia, un articolo o una battuta, poi tocca il segnalibro sul risultato per tenerlo qui.",
            "Forgetting curve": "Curva dell'oblio",
            "Average chance the deck is still remembered each day from today, projecting forward without further review.": "Probabilità media che il mazzo sia ancora ricordato ogni giorno a partire da oggi, proiettata in avanti senza ulteriori ripassi.",
            "Review some cards to start the curve.": "Ripassa alcune carte per avviare la curva.", "Target %d%%": "Obiettivo %d%%",
            "Today": "Oggi", "+%dd": "+%dg", "Most at risk": "Più a rischio",
            "Cards with the highest forgetting risk right now. Review these first.": "Carte con il maggior rischio di oblio in questo momento. Ripassa prima queste.",
            "No cards at risk — keep up the good work.": "Nessuna carta a rischio: continua così.", "Generate Artifact": "Genera artefatto",
            "Prompt": "Richiesta", "(none)": "(nessuna)", "Topics": "Argomenti", "Tone": "Tono", "Settings": "Impostazioni",
            "Language": "Lingua", "Level": "Livello", "Content": "Contenuto", "Original size": "Dimensione originale",
            "Original Prompt": "Richiesta originale", "Done": "Fine", "Review queue": "Coda di ripasso", "Status": "Stato",
            "The bars": "Le barre",
            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "Quattro barre verticali indicano quanta parte di questo mazzo richiede ancora attenzione. Ogni barra rappresenta circa un quarto delle tue carte: le barre si riempiono man mano che si accumulano carte non ancora studiate o di nuovo in scadenza. Studiare svuota le barre man mano che lo scheduler allontana quelle carte nel tempo.",
            "\"New\"": "\"Nuovo\"",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "\"Nuovo\" appare quando non hai ancora ripassato nessuna carta di questo mazzo. Tutte e quattro le barre sono piene perché l'intero mazzo è in attesa: tocca Riproduci per iniziare una sessione e le barre si ritirano man mano che valuti le carte.",
            "\"Up to date\"": "\"Aggiornato\"",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "\"Aggiornato\" appare quando non ci sono carte in scadenza e hai già studiato ogni carta almeno una volta: tutte e quattro le barre sono vuote. Torna più tardi e le barre si riempiranno man mano che le carte ricompaiono secondo la loro pianificazione.",
            "Clearing the bars": "Svuotare le barre",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "Tocca il pulsante Riproduci in cima a questo mazzo per iniziare una sessione di carte. Le barre si aggiornano dopo ogni sessione man mano che lo scheduler riordina le tue carte.",
            "Target retention": "Ritenzione obiettivo", "Current": "Attuale", "What it means": "Cosa significa",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "La ritenzione obiettivo è la probabilità con cui vuoi ricordare ogni carta alla prossima revisione. Al 90% accetti che circa 1 carta su 10 sarà dimenticata al momento del ripasso: lo scheduler punta esattamente a quel tasso di successo.",
            "How it affects scheduling": "Come influisce sulla pianificazione",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "Percentuali più alte stringono la pianificazione: le carte tornano prima, così dimentichi di meno, ma studi più spesso. Percentuali più basse allungano gli intervalli tra i ripassi, così studi di meno, al prezzo di dimenticare più carte lungo il percorso.",
            "Range": "Intervallo",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "Scegli tra 80% e 98%. 90% è il valore predefinito e quello che Anki consiglia alla maggior parte degli studenti: un compromesso equilibrato tra carico di studio e ritenzione.",
            "When to change it": "Quando cambiarlo",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "Alzalo un po' se troppe carte ti sembrano poco familiari quando ricompaiono. Abbassalo se ti senti sommerso dai ripassi quotidiani e puoi permetterti di dimenticarne qualcuna in più.",
            "View": "Vista", "Story": "Storia", "Line by line": "Riga per riga", "You asked for": "La tua richiesta",
            "Showing %d %@ for:": "Mostrati %d %@ per:", "Regenerate": "Rigenera", "Saving…": "Salvataggio…",
