            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "Quatro barras verticais mostram quanto deste baralho ainda precisa de atenção. Cada barra representa cerca de um quarto dos seus cartões — as barras enchem conforme se acumulam cartões ainda não estudados ou que venceram para outra passagem. Estudar esvazia as barras conforme o agendador empurra esses cartões para mais longe.",
            "\"New\"": "\"Novo\"",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "\"Novo\" aparece quando você ainda não revisou nenhum cartão deste baralho. As quatro barras estão cheias porque todo o baralho está pendente — toque em Reproduzir para iniciar uma sessão e as barras recuam conforme você avalia os cartões.",
            "\"Up to date\"": "\"Em dia\"",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "\"Em dia\" aparece quando não há cartões pendentes e você já estudou cada cartão pelo menos uma vez — as quatro barras ficam vazias. Volte mais tarde e as barras se encherão conforme os cartões reaparecem no cronograma.",
            "Clearing the bars": "Esvaziar as barras",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "Toque no botão Reproduzir no topo deste baralho para iniciar uma sessão de cartões. As barras se atualizam após cada sessão conforme o agendador reordena seus cartões.",
            "Target retention": "Retenção-alvo", "Current": "Atual", "What it means": "O que significa",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "A retenção-alvo é a probabilidade com que você quer lembrar cada cartão na próxima revisão. Em 90%, você aceita que cerca de 1 em 10 cartões terá sido esquecido na hora da revisão — o agendador mira exatamente nessa taxa de acerto.",
            "How it affects scheduling": "Como afeta o agendamento",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "Percentuais mais altos apertam o agendamento — os cartões voltam mais cedo, então você esquece menos, mas estuda com mais frequência. Percentuais mais baixos esticam os intervalos entre revisões, então você estuda menos, ao custo de esquecer mais cartões pelo caminho.",
            "Range": "Faixa",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "Escolha entre 80% e 98%. 90% é o padrão e o valor que o Anki recomenda para a maioria dos estudantes — um equilíbrio entre carga de estudo e retenção.",
            "When to change it": "Quando mudar",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "Aumente um pouco se cartões demais parecem desconhecidos quando reaparecem. Reduza se você se sente soterrado pelas revisões diárias e pode se dar ao luxo de esquecer mais alguns.",
            "View": "Exibição", "Story": "História", "Line by line": "Linha por linha", "You asked for": "O que você pediu",
            "Showing %d %@ for:": "Mostrando %d %@ para:", "Regenerate": "Regenerar", "Saving…": "Salvando…",
            "Create New Deck": "Criar novo baralho", "Add to Deck": "Adicionar ao baralho", "Something went wrong": "Algo deu errado",
            "Adding…": "Adicionando…", "Remove": "Remover", "Prompt sent to Claude": "Comando enviado ao Claude",
            "Raw JSON response": "Resposta JSON bruta", "Generation Details": "Detalhes da geração",
            "PUBLIC": "PÚBLICO", "YES": "SIM", "NO": "NÃO", "Coming soon": "Em breve", "TITLE": "TÍTULO",
            "Deck title": "Título do baralho", "COVER": "CAPA", "Save deck": "Salvar baralho", "New Deck": "Novo baralho",
            "Alphabetized": "Alfabético", "Original": "Original", "Conversation": "Conversa", "News Article": "Notícia",
            "Songs": "Músicas", "Poems": "Poemas", "Jokes": "Piadas",
            "Add Synonyms": "Adicionar sinônimos", "Add Antonyms": "Adicionar antônimos", "Create Sentence": "Criar frase",
            "Add Plurals": "Adicionar plurais", "Add Conjugations": "Adicionar conjugações", "Add Similar Sounding Words": "Adicionar palavras de som parecido", "Add Similar-Looking Words": "Adicionar palavras de aparência semelhante",
            "Gradient": "Gradiente", "Audio": "Áudio", "Black": "Preto", "White": "Branco", "Dark Cherry": "Cereja escura",
            "Pleasant": "Agradável", "Mouths": "Bocas", "Mouths 2": "Bocas 2", "Speakers": "Falantes", "Speakers 2": "Falantes 2",
            "Porcelain": "Porcelana", "Porcelain 2": "Porcelana 2", "Byzantine": "Bizantino", "Byzantine 2": "Bizantino 2",
            "Still Life": "Natureza-morta", "Chinese Village": "Vila chinesa",
            "Colors": "Cores", "Graphics": "Gráficos", "Art": "Arte", "Medieval": "Medieval",
        ],
        .ja: [
            "Rename": "名前を変更", "Merge into": "統合先", "Download as audio": "音声としてダウンロード",
            "Export as CSV": "CSVとして書き出す", "Delete deck": "デッキを削除", "Merged": "統合しました", "OK": "OK",
            "Added %d %@ to \"%@\".": "%d件の%@を「%@」に追加しました。", "Delete this deck?": "このデッキを削除しますか？",
            "Delete": "削除", "Cancel": "キャンセル", "This can't be undone.": "この操作は取り消せません。",
            "Couldn't generate more": "これ以上生成できませんでした", "Delete this artifact?": "このアーティファクトを削除しますか？",
            "Delete artifact": "アーティファクトを削除", "%d due": "%d件 期限", "New": "新規", "Up to date": "最新",
            "CONTENT": "コンテンツ", "ARTIFACTS": "アーティファクト", "STATS": "統計", "Copy": "コピー",
            "Generating…": "生成中…", "Generate More": "さらに生成", "No artifacts saved yet": "保存されたアーティファクトはまだありません",
            "Open Generate, make a story, conversation, song, poem, news article, or joke — then tap the bookmark on the result to keep it here.": "「生成」を開いて、ストーリー・会話・歌・詩・ニュース記事・ジョークを作り、結果のブックマークをタップするとここに保存できます。",
            "Forgetting curve": "忘却曲線",
            "Average chance the deck is still remembered each day from today, projecting forward without further review.": "今日から先、追加の復習をしない場合に、デッキを毎日どれだけ覚えているかの平均確率。",
            "Review some cards to start the curve.": "カードを復習するとカーブが始まります。", "Target %d%%": "目標 %d%%",
            "Today": "今日", "+%dd": "+%d日", "Most at risk": "最もリスクが高い",
            "Cards with the highest forgetting risk right now. Review these first.": "今もっとも忘れやすいカード。まずこれらを復習しましょう。",
            "No cards at risk — keep up the good work.": "リスクのあるカードはありません。この調子で。", "Generate Artifact": "アーティファクトを生成",
            "Prompt": "プロンプト", "(none)": "（なし）", "Topics": "トピック", "Tone": "トーン", "Settings": "設定",
            "Language": "言語", "Level": "レベル", "Content": "コンテンツ", "Original size": "元のサイズ",
            "Original Prompt": "元のプロンプト", "Done": "完了", "Review queue": "復習キュー", "Status": "ステータス",
            "The bars": "バーについて",
            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "4本の縦棒は、このデッキのうちどれだけまだ対応が必要かを示します。各棒はおおよそカードの4分の1を表し、まだ学習していないカードや再び期限が来たカードがたまると棒が満ちます。学習すると、スケジューラがそれらのカードを先送りするにつれて棒が減っていきます。",
            "\"New\"": "「新規」",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "「新規」は、このデッキのカードをまだ一枚も復習していないときに表示されます。デッキ全体が保留中のため4本の棒がすべて満ちています。再生をタップしてセッションを始めると、カードを評価するにつれて棒が下がります。",
            "\"Up to date\"": "「最新」",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "「最新」は、期限のカードがなく、すべてのカードを少なくとも一度学習し終えたときに表示されます。4本の棒はすべて空です。後で戻ってくると、スケジュールに従ってカードが再び現れるにつれて棒が満ちていきます。",
            "Clearing the bars": "棒を空にするには",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "このデッキの上部にある再生ボタンをタップしてフラッシュカードのセッションを始めます。セッションごとに、スケジューラがカードを組み替えるにつれて棒が更新されます。",
            "Target retention": "目標保持率", "Current": "現在", "What it means": "意味",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "目標保持率は、各カードが次に復習に出てくるときに覚えていたい確率です。90%では、復習の時点でおよそ10枚に1枚は忘れていることを受け入れることになり、スケジューラはまさにその的中率を目指します。",
            "How it affects scheduling": "スケジュールへの影響",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "割合を高くするとスケジュールが詰まり、カードが早く戻ってくるので忘れる数は減りますが、学習頻度は上がります。割合を低くすると復習の間隔が広がり、学習は減りますが、その分より多くのカードを忘れることになります。",
            "Range": "範囲",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "80%から98%の間で選びます。90%が既定値で、Ankiが多くの学習者に推奨する値です。学習量と保持率のバランスの取れた妥協点です。",
            "When to change it": "変更するタイミング",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "再び現れたときに知らないと感じるカードが多すぎる場合は少し上げましょう。毎日の復習に追われていて、もう少し忘れても構わない場合は下げましょう。",
            "View": "表示", "Story": "ストーリー", "Line by line": "一行ずつ", "You asked for": "リクエスト内容",
            "Showing %d %@ for:": "%d件の%@を表示中：", "Regenerate": "再生成", "Saving…": "保存中…",
            "Create New Deck": "新しいデッキを作成", "Add to Deck": "デッキに追加", "Something went wrong": "問題が発生しました",
            "Adding…": "追加中…", "Remove": "削除", "Prompt sent to Claude": "Claudeに送信したプロンプト",
            "Raw JSON response": "生のJSONレスポンス", "Generation Details": "生成の詳細",
            "PUBLIC": "公開", "YES": "はい", "NO": "いいえ", "Coming soon": "近日公開", "TITLE": "タイトル",
            "Deck title": "デッキのタイトル", "COVER": "カバー", "Save deck": "デッキを保存", "New Deck": "新しいデッキ",
            "Alphabetized": "アルファベット順", "Original": "オリジナル", "Conversation": "会話", "News Article": "ニュース記事",
            "Songs": "歌", "Poems": "詩", "Jokes": "ジョーク",
            "Add Synonyms": "類義語を追加", "Add Antonyms": "対義語を追加", "Create Sentence": "文を作成",
            "Add Plurals": "複数形を追加", "Add Conjugations": "活用を追加", "Add Similar Sounding Words": "似た音の単語を追加", "Add Similar-Looking Words": "似た形の単語を追加",
            "Gradient": "グラデーション", "Audio": "オーディオ", "Black": "ブラック", "White": "ホワイト", "Dark Cherry": "ダークチェリー",
            "Pleasant": "プレザント", "Mouths": "口", "Mouths 2": "口 2", "Speakers": "話者", "Speakers 2": "話者 2",
            "Porcelain": "磁器", "Porcelain 2": "磁器 2", "Byzantine": "ビザンチン", "Byzantine 2": "ビザンチン 2",
            "Still Life": "静物", "Chinese Village": "中国の村",
            "Colors": "カラー", "Graphics": "グラフィック", "Art": "アート", "Medieval": "中世",
        ],
        .zhHans: [
            "Rename": "重命名", "Merge into": "合并到", "Download as audio": "下载为音频",
            "Export as CSV": "导出为 CSV", "Delete deck": "删除卡组", "Merged": "已合并", "OK": "好",
            "Added %d %@ to \"%@\".": "已将 %d 个%@添加到\"%@\"。", "Delete this deck?": "删除此卡组？",
            "Delete": "删除", "Cancel": "取消", "This can't be undone.": "此操作无法撤销。",
            "Couldn't generate more": "无法生成更多", "Delete this artifact?": "删除此内容？",
            "Delete artifact": "删除内容", "%d due": "%d 张待复习", "New": "新", "Up to date": "已是最新",
            "CONTENT": "内容", "ARTIFACTS": "生成内容", "STATS": "统计", "Copy": "复制",
            "Generating…": "生成中…", "Generate More": "生成更多", "No artifacts saved yet": "尚未保存任何生成内容",
            "Open Generate, make a story, conversation, song, poem, news article, or joke — then tap the bookmark on the result to keep it here.": "打开\"生成\"，创作故事、对话、歌曲、诗歌、新闻文章或笑话，然后点按结果上的书签即可保存到这里。",
            "Forgetting curve": "遗忘曲线",
            "Average chance the deck is still remembered each day from today, projecting forward without further review.": "从今天起，在不再复习的情况下，卡组每天仍被记住的平均概率。",
            "Review some cards to start the curve.": "复习一些卡片以生成曲线。", "Target %d%%": "目标 %d%%",
            "Today": "今天", "+%dd": "+%d天", "Most at risk": "最易遗忘",
            "Cards with the highest forgetting risk right now. Review these first.": "目前最容易遗忘的卡片。先复习这些。",
            "No cards at risk — keep up the good work.": "没有处于风险中的卡片——继续保持。", "Generate Artifact": "生成内容",
            "Prompt": "提示词", "(none)": "（无）", "Topics": "主题", "Tone": "语气", "Settings": "设置",
            "Language": "语言", "Level": "级别", "Content": "内容", "Original size": "原始数量",
            "Original Prompt": "原始提示词", "Done": "完成", "Review queue": "复习队列", "Status": "状态",
            "The bars": "关于这些竖条",
            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "四条竖条显示这个卡组还有多少需要关注。每条大约代表你四分之一的卡片——当尚未学习或又到期的卡片累积时，竖条会填满。学习会使竖条下降，因为调度器会把这些卡片安排到更远的将来。",
            "\"New\"": "\"新\"",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "当你还没有复习过这个卡组中的任何卡片时会显示\"新\"。四条竖条都是满的，因为整个卡组都待处理——点按播放开始一次学习，随着你为卡片评级，竖条会回落。",
            "\"Up to date\"": "\"已是最新\"",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "当前没有到期卡片，且你已至少学习过每张卡片一次时，会显示\"已是最新\"——四条竖条都为空。稍后再来，随着卡片按计划重新出现，竖条会重新填满。",
            "Clearing the bars": "清空竖条",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "点按此卡组顶部的播放按钮开始一次抽认卡学习。每次学习后，随着调度器重新安排你的卡片，竖条会更新。",
            "Target retention": "目标记忆率", "Current": "当前", "What it means": "含义",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "目标记忆率是你希望在每张卡片下次复习时仍能记住的概率。设为 90% 时，你接受到复习时大约每 10 张有 1 张会被遗忘——调度器正是以这个命中率为目标。",
            "How it affects scheduling": "对排程的影响",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "百分比越高，排程越紧——卡片更快回来，遗忘更少，但学习更频繁。百分比越低，复习间隔越长，学习更少，代价是途中会遗忘更多卡片。",
            "Range": "范围",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "在 80% 到 98% 之间选择。90% 是默认值，也是 Anki 向大多数学习者推荐的值——在学习量与记忆率之间取得平衡。",
            "When to change it": "何时更改",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "如果卡片重新出现时你觉得太多都不熟悉，就把它调高一点。如果你被每日复习压得喘不过气、且能承受多忘一些，就把它调低。",
            "View": "视图", "Story": "故事", "Line by line": "逐行", "You asked for": "你的请求",
            "Showing %d %@ for:": "正在显示 %d 个%@，用于：", "Regenerate": "重新生成", "Saving…": "保存中…",
            "Create New Deck": "创建新卡组", "Add to Deck": "添加到卡组", "Something went wrong": "出错了",
            "Adding…": "添加中…", "Remove": "移除", "Prompt sent to Claude": "发送给 Claude 的提示词",
            "Raw JSON response": "原始 JSON 响应", "Generation Details": "生成详情",
            "PUBLIC": "公开", "YES": "是", "NO": "否", "Coming soon": "敬请期待", "TITLE": "标题",
            "Deck title": "卡组标题", "COVER": "封面", "Save deck": "保存卡组", "New Deck": "新卡组",
            "Alphabetized": "按字母", "Original": "原始顺序", "Conversation": "对话", "News Article": "新闻文章",
            "Songs": "歌曲", "Poems": "诗歌", "Jokes": "笑话",
            "Add Synonyms": "添加同义词", "Add Antonyms": "添加反义词", "Create Sentence": "造句",
            "Add Plurals": "添加复数", "Add Conjugations": "添加变位", "Add Similar Sounding Words": "添加发音相近的词", "Add Similar-Looking Words": "添加字形相近的词",
            "Gradient": "渐变", "Audio": "音频", "Black": "黑色", "White": "白色", "Dark Cherry": "深樱红",
            "Pleasant": "清新", "Mouths": "嘴", "Mouths 2": "嘴 2", "Speakers": "说话者", "Speakers 2": "说话者 2",
            "Porcelain": "瓷器", "Porcelain 2": "瓷器 2", "Byzantine": "拜占庭", "Byzantine 2": "拜占庭 2",
            "Still Life": "静物", "Chinese Village": "中国村庄",
            "Colors": "颜色", "Graphics": "图形", "Art": "艺术", "Medieval": "中世纪",
