        .ko: [
            "Rename": "이름 변경", "Merge into": "병합 대상", "Download as audio": "오디오로 다운로드",
            "Export as CSV": "CSV로 내보내기", "Delete deck": "덱 삭제", "Merged": "병합됨", "OK": "확인",
            "Added %d %@ to \"%@\".": "%d개의 %@을(를) \"%@\"에 추가했습니다.", "Delete this deck?": "이 덱을 삭제할까요?",
            "Delete": "삭제", "Cancel": "취소", "This can't be undone.": "되돌릴 수 없습니다.",
            "Couldn't generate more": "더 생성할 수 없습니다", "Delete this artifact?": "이 아티팩트를 삭제할까요?",
            "Delete artifact": "아티팩트 삭제", "%d due": "%d개 예정", "New": "새로움", "Up to date": "최신 상태",
            "CONTENT": "콘텐츠", "ARTIFACTS": "아티팩트", "STATS": "통계", "Copy": "복사",
            "Generating…": "생성 중…", "Generate More": "더 생성", "No artifacts saved yet": "아직 저장된 아티팩트가 없습니다",
            "Open Generate, make a story, conversation, song, poem, news article, or joke — then tap the bookmark on the result to keep it here.": "\"생성\"을 열어 이야기, 대화, 노래, 시, 뉴스 기사 또는 농담을 만든 뒤, 결과의 북마크를 탭하면 여기에 보관됩니다.",
            "Forgetting curve": "망각 곡선",
            "Average chance the deck is still remembered each day from today, projecting forward without further review.": "오늘부터 추가 복습 없이 앞으로 각 날짜에 덱을 여전히 기억할 평균 확률입니다.",
            "Review some cards to start the curve.": "카드를 복습하면 곡선이 시작됩니다.", "Target %d%%": "목표 %d%%",
            "Today": "오늘", "+%dd": "+%d일", "Most at risk": "가장 위험함",
            "Cards with the highest forgetting risk right now. Review these first.": "지금 가장 잊기 쉬운 카드입니다. 이것부터 복습하세요.",
            "No cards at risk — keep up the good work.": "위험한 카드가 없습니다 — 계속 잘하고 있어요.", "Generate Artifact": "아티팩트 생성",
            "Prompt": "프롬프트", "(none)": "(없음)", "Topics": "주제", "Tone": "어조", "Settings": "설정",
            "Language": "언어", "Level": "레벨", "Content": "콘텐츠", "Original size": "원래 크기",
            "Original Prompt": "원래 프롬프트", "Done": "완료", "Review queue": "복습 대기열", "Status": "상태",
            "The bars": "막대에 대하여",
            "Four vertical bars track how much of this deck still needs attention. Each bar represents roughly a quarter of your cards — bars fill as cards stack up that haven't been studied yet or have come due for another pass. Studying drains the bars as the scheduler pushes those cards further out.": "네 개의 세로 막대는 이 덱에서 아직 신경 써야 할 양을 보여 줍니다. 각 막대는 카드의 약 4분의 1을 나타내며, 아직 공부하지 않았거나 다시 복습할 때가 된 카드가 쌓이면 막대가 채워집니다. 공부하면 스케줄러가 그 카드들을 뒤로 미루면서 막대가 줄어듭니다.",
            "\"New\"": "\"새로움\"",
            "\"New\" appears when you haven't reviewed any card in this deck yet. All four bars are filled because the entire deck is pending — tap Play to start a session and the bars retreat as you grade cards.": "\"새로움\"은 이 덱의 카드를 아직 하나도 복습하지 않았을 때 나타납니다. 덱 전체가 대기 중이라 네 막대가 모두 차 있습니다 — 재생을 탭해 세션을 시작하면 카드를 평가할수록 막대가 줄어듭니다.",
            "\"Up to date\"": "\"최신 상태\"",
            "\"Up to date\" appears when no cards are currently due and you've already studied every card at least once — all four bars sit empty. Come back later and bars will refill as cards reappear on their schedule.": "\"최신 상태\"는 현재 예정된 카드가 없고 모든 카드를 최소 한 번 공부했을 때 나타납니다 — 네 막대가 모두 비어 있습니다. 나중에 다시 오면 카드가 일정에 따라 다시 나타나면서 막대가 채워집니다.",
            "Clearing the bars": "막대 비우기",
            "Tap the Play button at the top of this deck to start a flashcard session. The bars update after each session as the scheduler reshuffles your cards.": "이 덱 상단의 재생 버튼을 탭해 플래시카드 세션을 시작하세요. 세션이 끝날 때마다 스케줄러가 카드를 다시 배치하면서 막대가 업데이트됩니다.",
            "Target retention": "목표 기억률", "Current": "현재", "What it means": "의미",
            "Target retention is the probability you want to remember each card when it next comes up for review. At 90%, you're accepting that roughly 1 in 10 cards will be forgotten by the time they're reviewed — the scheduler aims for exactly that hit rate.": "목표 기억률은 각 카드가 다음 복습에 나올 때 기억하고 싶은 확률입니다. 90%로 설정하면 복습 시점에 대략 10장 중 1장은 잊게 됨을 받아들이는 것이며, 스케줄러는 정확히 그 적중률을 목표로 합니다.",
            "How it affects scheduling": "일정에 미치는 영향",
            "Higher percentages tighten the schedule — cards return sooner so you forget fewer, but you'll study more often. Lower percentages stretch the intervals between reviews so you study less, at the cost of forgetting more cards along the way.": "비율을 높이면 일정이 촘촘해집니다 — 카드가 더 빨리 돌아와 덜 잊지만 더 자주 공부하게 됩니다. 비율을 낮추면 복습 간격이 늘어나 덜 공부하지만, 그만큼 더 많은 카드를 잊게 됩니다.",
            "Range": "범위",
            "Choose between 80% and 98%. 90% is the default and the value Anki recommends for most learners — a balanced trade-off between study load and retention.": "80%에서 98% 사이에서 선택하세요. 90%가 기본값이며 Anki가 대부분의 학습자에게 권장하는 값으로, 학습량과 기억률 사이의 균형점입니다.",
            "When to change it": "언제 바꿀까",
            "Nudge it up if too many cards feel unfamiliar when they reappear. Bring it down if you feel buried in daily reviews and can afford to forget a few more.": "카드가 다시 나타날 때 낯선 것이 너무 많으면 조금 올리세요. 매일의 복습에 파묻힌 느낌이고 조금 더 잊어도 괜찮다면 낮추세요.",
            "View": "보기", "Story": "이야기", "Line by line": "줄별", "You asked for": "요청한 내용",
            "Showing %d %@ for:": "%d개의 %@ 표시 중:", "Regenerate": "다시 생성", "Saving…": "저장 중…",
            "Create New Deck": "새 덱 만들기", "Add to Deck": "덱에 추가", "Something went wrong": "문제가 발생했습니다",
            "Adding…": "추가 중…", "Remove": "제거", "Prompt sent to Claude": "Claude에 보낸 프롬프트",
            "Raw JSON response": "원시 JSON 응답", "Generation Details": "생성 세부 정보",
            "PUBLIC": "공개", "YES": "예", "NO": "아니요", "Coming soon": "곧 제공 예정", "TITLE": "제목",
            "Deck title": "덱 제목", "COVER": "커버", "Save deck": "덱 저장", "New Deck": "새 덱",
            "Alphabetized": "가나다순", "Original": "원래 순서", "Conversation": "대화", "News Article": "뉴스 기사",
            "Songs": "노래", "Poems": "시", "Jokes": "농담",
            "Add Synonyms": "동의어 추가", "Add Antonyms": "반의어 추가", "Create Sentence": "문장 만들기",
            "Add Plurals": "복수형 추가", "Add Conjugations": "활용형 추가", "Add Similar Sounding Words": "발음이 비슷한 단어 추가", "Add Similar-Looking Words": "모양이 비슷한 단어 추가",
            "Gradient": "그러데이션", "Audio": "오디오", "Black": "검정", "White": "흰색", "Dark Cherry": "다크 체리",
            "Pleasant": "산뜻함", "Mouths": "입", "Mouths 2": "입 2", "Speakers": "화자", "Speakers 2": "화자 2",
            "Porcelain": "도자기", "Porcelain 2": "도자기 2", "Byzantine": "비잔틴", "Byzantine 2": "비잔틴 2",
            "Still Life": "정물", "Chinese Village": "중국 마을",
